#if USE_TRACE == 1

Boolean trace_init ( Sio sio )
{
    UInt8 i ;    
    
    trace_vars.func = NULL ;
	
    trace_vars.q_free    = q_create()   ; 
    trace_vars.q_pending = q_create()   ;	
	trace_vars.sio       = sio          ;
	    
	for( i = 0 ; i < TRACE_Q_SIZE ; i ++ )
    {
       void *trace_q_msg ; 
       
	   trace_q_msg = os_mem_request( sizeof( struct s_Trace_Q_Msg ) );
		                  
       q_insert( trace_vars.q_free , (Q_Msg*)trace_q_msg  );            
       q_assign( trace_vars.q_free , (Q_Msg*)trace_q_msg  );
    }

  //  ATOMIC( os_mem_fail_func = trace_mem_error );

    /*init_trace_tsk:*/
	{
		Tsk tsk ; 
	
		tsk = os_tsk_create (trace_tsk , TRACE_TSK_PRI , TRACE_TSK_STK , 0 , TRACE_TSK_NAME  ) ;	
    
		os_tsk_start (tsk , 0) ;        
	}
	
	/*   some new printf init */
	init_printf(NULL,putc1);                           
    
    return TRUE ; 
} 

/*--------------------------------------------------------------------------*/
void    trace_func_update (Trace_Dbg_Func func) 
{
  ATOMIC(trace_vars.func = func) ;    
}

#endif

